"""DMGHG Local Native Bridge Service.

Provides a loopback-only (127.0.0.1) HTTP bridge between HikerView PC engine
and the installed DMGHG desktop application native library (electron_bridge.dll).
"""
import argparse
import ctypes
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from pathlib import Path
import socket
import sys
import tempfile
import threading
import urllib.parse

READ_COMMANDS = {
    "app.ping",
    "catalog.get_channels",
    "catalog.get_banners",
    "catalog.get_video_list",
    "catalog.search_video",
    "catalog.get_video_key",
    "catalog.get_video_detail",
    "catalog.get_channel_detail",
    "video.play",
}


def installed_version(exe):
    """Read PE version metadata; the resolver rejects unsupported client versions."""
    version = ctypes.windll.version
    size = version.GetFileVersionInfoSizeW(str(exe), None)
    if not size:
        raise RuntimeError("Cannot read the installed application's version metadata")
    buffer = ctypes.create_string_buffer(size)
    if not version.GetFileVersionInfoW(str(exe), 0, size, buffer):
        raise RuntimeError("Cannot read application version info")
    info = ctypes.c_void_p()
    length = ctypes.c_uint()
    if not version.VerQueryValueW(buffer, "\\", ctypes.byref(info), ctypes.byref(length)):
        raise RuntimeError("Application version structure is missing")
    fields = ctypes.cast(info, ctypes.POINTER(ctypes.c_uint32))
    if fields[0] != 0xFEEF04BD or length.value < 52:
        raise RuntimeError("Application version structure is invalid")
    return f"{fields[2] >> 16}.{fields[2] & 65535}.{fields[3] >> 16}"


class Bridge:
    """Encapsulates the installed native electron_bridge.dll service."""

    def __init__(self, app_dir):
        if os.name != "nt":
            raise RuntimeError("The installed bridge requires Windows x64 Python")
        self.app_dir = Path(app_dir).resolve(strict=True)
        self.dll_path = self.app_dir / "electron_bridge.dll"
        if not self.dll_path.is_file():
            raise RuntimeError(f"electron_bridge.dll is missing in {self.app_dir}")
        self.state_root = Path(tempfile.mkdtemp(prefix="dmghg-headless-"))
        os.environ["DMGHG_TEST_DATA_ROOT"] = str(self.state_root)
        os.environ["RUST_LOG"] = "error"
        self.dll = ctypes.CDLL(str(self.dll_path))
        self.dll.dmghg_service_new.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
        self.dll.dmghg_service_new.restype = ctypes.c_void_p
        self.dll.dmghg_service_handle_command_json.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.dll.dmghg_service_handle_command_json.restype = ctypes.c_void_p
        self.dll.dmghg_string_free.argtypes = [ctypes.c_void_p]
        self.dll.dmghg_service_free.argtypes = [ctypes.c_void_p]
        self.lock = threading.RLock()
        self.version = installed_version(self.app_dir / "dmghg.exe")
        self.handle = self.dll.dmghg_service_new(b"dmghg-flutter", self.version.encode("ascii"))
        if not self.handle:
            raise RuntimeError("The installed bridge could not initialize")

    def call(self, command, payload=None):
        if command not in READ_COMMANDS:
            raise ValueError(f"Command '{command}' is outside the read-only inspection allowlist")
        request = {
            "request_id": "bridge-rpc",
            "protocol_version": 1,
            "command": command,
            "payload": payload or {}
        }
        with self.lock:
            previous = Path.cwd()
            try:
                os.chdir(self.app_dir)
                ptr = self.dll.dmghg_service_handle_command_json(
                    self.handle, json.dumps(request, ensure_ascii=False).encode("utf-8")
                )
                if not ptr:
                    raise RuntimeError("Bridge returned a null response")
                try:
                    response = json.loads(ctypes.string_at(ptr).decode("utf-8"))
                finally:
                    self.dll.dmghg_string_free(ptr)
            finally:
                os.chdir(previous)
        if response.get("ok") is not True:
            error = response.get("error", {})
            raise RuntimeError(f"{error.get('code')}: {error.get('message')}")
        return response.get("data")

    def close(self):
        with self.lock:
            if self.handle:
                self.dll.dmghg_service_free(self.handle)
                self.handle = None


class BridgeHandler(BaseHTTPRequestHandler):
    timeout = 5.0
    server_version = "DMGHGBridge/1.0"

    def setup(self):
        super().setup()
        if self.request:
            self.request.settimeout(5.0)

    def handle_one_request(self):
        try:
            super().handle_one_request()
        except (socket.timeout, TimeoutError):
            self.close_connection = True
            try:
                self.send_error(408, "Request Timeout")
            except Exception:
                pass

    def _send_json(self, status_code, data):
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(body)

    def _send_error(self, status_code, message, code=None):
        self._send_json(status_code, {
            "ok": False,
            "error": {
                "code": code or status_code,
                "message": str(message)
            }
        })

    def do_GET(self):
        bridge = self.server.bridge
        parsed = urllib.parse.urlsplit(self.path)
        path = parsed.path
        query = urllib.parse.parse_qs(parsed.query)

        try:
            if path in ("/ping", "/api/ping"):
                self._send_json(200, {
                    "ok": True,
                    "version": bridge.version,
                    "status": "running"
                })
            elif path in ("/channels", "/api/channels"):
                channels = bridge.call("catalog.get_channels")
                self._send_json(200, {
                    "ok": True,
                    "data": channels,
                    "channels": channels
                })
            elif path in ("/list", "/api/list"):
                raw_channel = query.get("channel", [None])[0]
                channel = int(raw_channel) if raw_channel is not None else 20
                raw_page = query.get("page", [None])[0]
                page = int(raw_page) if raw_page is not None else 1
                data = bridge.call("catalog.get_video_list", {"channel": channel, "page": page})
                self._send_json(200, {
                    "ok": True,
                    "data": data,
                    "items": data.get("items", []) if isinstance(data, dict) else []
                })
            elif path in ("/search", "/api/search"):
                key = query.get("key", [""])[0]
                page = str(query.get("page", ["1"])[0])
                data = bridge.call("catalog.search_video", {"key": key, "page": page})
                self._send_json(200, {
                    "ok": True,
                    "data": data,
                    "items": data.get("items", []) if isinstance(data, dict) else []
                })
            elif path in ("/detail", "/api/detail"):
                item_id = str(query.get("id", [""])[0])
                if not item_id:
                    self._send_error(400, "Missing required query parameter 'id'")
                    return
                data = bridge.call("catalog.get_video_detail", {"id": item_id})
                self._send_json(200, {
                    "ok": True,
                    "data": data
                })
            elif path in ("/play", "/api/play"):
                item_id = str(query.get("id", [""])[0])
                part = str(query.get("part", [""])[0])
                play_code = str(query.get("play", ["cn"])[0])
                if not item_id or not part:
                    self._send_error(400, "Missing required query parameters 'id' or 'part'")
                    return
                data = bridge.call("video.play", {
                    "id": item_id,
                    "part": part,
                    "play": play_code,
                    "resolve": True
                })
                self._send_json(200, {
                    "ok": True,
                    "data": data
                })
            else:
                self._send_error(404, f"Endpoint '{path}' not found")
        except ValueError as e:
            self._send_error(400, str(e))
        except Exception as e:
            self._send_error(500, str(e))

    def do_POST(self):
        bridge = self.server.bridge
        parsed = urllib.parse.urlsplit(self.path)
        path = parsed.path

        content_len_header = self.headers.get("Content-Length")
        if not content_len_header:
            self._send_error(400, "Missing Content-Length header")
            return
        try:
            length = int(content_len_header)
        except ValueError:
            self._send_error(400, "Invalid Content-Length header")
            return
        if length > 1024 * 1024:
            self._send_error(413, "Request body size exceeds 1MB limit")
            return

        try:
            body = self.rfile.read(length)
            req = json.loads(body.decode("utf-8")) if body else {}
        except Exception as e:
            self._send_error(400, f"Malformed JSON body: {e}")
            return

        try:
            if path in ("/call", "/api/call"):
                command = req.get("command")
                if not command:
                    self._send_error(400, "Missing required field 'command'")
                    return
                if command not in READ_COMMANDS:
                    self._send_error(403, f"Command '{command}' is not in the read-only allowlist")
                    return
                payload = req.get("payload") or {}
                data = bridge.call(command, payload)
                self._send_json(200, {
                    "ok": True,
                    "data": data
                })
            elif path in ("/play", "/api/play"):
                item_id = str(req.get("id", ""))
                part = str(req.get("part", ""))
                play_code = str(req.get("play", "cn"))
                if not item_id or not part:
                    self._send_error(400, "Missing required fields 'id' or 'part'")
                    return
                data = bridge.call("video.play", {
                    "id": item_id,
                    "part": part,
                    "play": play_code,
                    "resolve": True
                })
                self._send_json(200, {
                    "ok": True,
                    "data": data
                })
            else:
                self._send_error(404, f"Endpoint '{path}' not found")
        except ValueError as e:
            self._send_error(400, str(e))
        except Exception as e:
            self._send_error(500, str(e))

    def log_message(self, format, *args):
        # Suppress noisy standard request logs
        pass


class ThreadedBridgeServer(ThreadingHTTPServer):
    allow_reuse_address = True
    daemon_threads = True

    def __init__(self, server_address, RequestHandlerClass, bridge):
        self.bridge = bridge
        super().__init__(server_address, RequestHandlerClass)


def run_server(app_dir, port=18002, host="127.0.0.1"):
    if host not in ("127.0.0.1", "localhost"):
        raise ValueError(f"Security error: bridge can only bind to 127.0.0.1, got '{host}'")
    bridge = Bridge(app_dir)
    server = ThreadedBridgeServer(("127.0.0.1", port), BridgeHandler, bridge)
    try:
        print(f"Bridge listening on [REDACTED_URL] (app-dir: {app_dir})")
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        bridge.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--app-dir", required=True, help="Installed DMGHG root path containing electron_bridge.dll")
    parser.add_argument("--port", type=int, default=18002, help="Port to listen on (default: 18002, engine supported: 18000, 18001, 18002)")
    parser.add_argument("--host", default="127.0.0.1", help="Bind host (strictly loopback 127.0.0.1 only)")
    args = parser.parse_args()

    if args.host not in ("127.0.0.1", "localhost"):
        sys.stderr.write(f"Error: Host '{args.host}' is forbidden. Bridge must only bind to 127.0.0.1.\n")
        sys.exit(1)

    run_server(args.app_dir, args.port, args.host)


if __name__ == "__main__":
    main()

